#!/usr/bin/env python3
import sys
from datetime import datetime

def parse_date(date_str):
    """Try to parse a date string using common formats."""
    formats = [
        '%Y-%m-%d',      # 2023-5-1
        '%Y/%m/%d',      # 2023/5/1
        '%Y.%m.%d',      # 2023.5.1
        '%d-%m-%Y',      # 1-5-2023
        '%d/%m/%Y',      # 1/5/2023
        '%m-%d-%Y',      # 5-1-2023
        '%m/%d/%Y',      # 5/1/2023
        '%Y-%m-%d %H:%M:%S',  # 2023-5-1 12:30:45
        '%Y/%m/%d %H:%M:%S',  # 2023/5/1 12:30:45
        '%Y-%m-%dT%H:%M:%S',  # 2023-5-1T12:30:45
        '%Y-%m-%d %H:%M',     # 2023-5-1 12:30
        '%Y/%m/%d %H:%M',     # 2023/5/1 12:30
    ]

    for fmt in formats:
        try:
            return datetime.strptime(date_str, fmt)
        except ValueError:
            continue

    # If none of the formats work, try to handle single-digit month/day
    # by adding leading zeros
    try:
        parts = date_str.split('-')
        if len(parts) == 3:
            normalized = f"{parts[0]}-{parts[1].zfill(2)}-{parts[2].zfill(2)}"
            return datetime.strptime(normalized, '%Y-%m-%d')
    except:
        pass

    try:
        parts = date_str.split('/')
        if len(parts) == 3:
            normalized = f"{parts[0]}/{parts[1].zfill(2)}/{parts[2].zfill(2)}"
            return datetime.strptime(normalized, '%Y/%m/%d')
    except:
        pass

    return None

def main():
    if len(sys.argv) < 3:
        print("Usage: date-format <date-string> <format-string>", file=sys.stderr)
        sys.exit(1)

    date_str = sys.argv[1]
    format_str = sys.argv[2]

    parsed_date = parse_date(date_str)

    if parsed_date is None:
        print(f"Error: Could not parse date string '{date_str}'", file=sys.stderr)
        sys.exit(1)

    try:
        formatted = parsed_date.strftime(format_str)
        print(formatted)
    except Exception as e:
        print(f"Error: Could not format date with format '{format_str}': {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == '__main__':
    main()
EOF
chmod +x /usr/local/bin/date-format
